svg.script:

var activePos = null;
var activeId = null;

var COMPONENT_POS_MAP = {
  'mittelpfette': '03c',
  'fronttraeger': '03d',
  'pfette-links-1': '03a',
  'pfette-links-2': '03b',
  'wandholz-fenster': '02',
  'wandpfette-rechts': '01',
  'sparren': '07',
  'balkenwinkel': '13b',
  'pfosten-fp1': '04a',
  'pfosten-fp2': '04b',
  'balkenschuh-1': '10',
  'balkenschuh-2': '10',
  'balkenschuh-3': '10',
  'balkenschuh-4': '10',
  'balkenschuh-5': '10b',
  'injektionsanker': '08',
  'm16-staebe': '01',
  'bolzen-m12': '15e',
  'tellerkopf-sparren': '16',
  'tellerkopf-pfosten': '15b',
  'spenglerschrauben': '15c',
  'csa-schrauben': '14',
  'pfostenschuh': '09'
};

function deselectAll() {
  activePos = null;
  activeId = null;
  document.querySelectorAll('.plan-pos-badge').forEach(function(b) {
    b.classList.remove('active-badge');
  });
  document.querySelectorAll('.comp-hitbox').forEach(function(h) {
    h.classList.remove('active');
  });
}

function highlightPosBadge(pos) {
  document.querySelectorAll('.plan-pos-badge').forEach(function(b) {
    b.classList.remove('active-badge');
  });
  if (!pos) return;
  var cleanPos = pos.replace(/^pos\.?\s*/i, '').trim();
  var matches = document.querySelectorAll('.plan-pos-badge[data-pos="' + cleanPos + '"]');
  matches.forEach(function(b) {
    b.classList.add('active-badge');
  });
}

function selectHitbox(id, pos) {
  if (!pos && id && COMPONENT_POS_MAP[id]) {
    pos = COMPONENT_POS_MAP[id];
  }
  if (activePos === pos || (id && activeId === id)) {
    deselectAll();
    return;
  }
  deselectAll();
  activeId = id;
  activePos = pos;
  if (id) {
    document.querySelectorAll('.comp-hitbox[data-id="' + id + '"]').forEach(function(h) {
      h.classList.add('active');
    });
  }
  if (pos) {
    highlightPosBadge(pos);
  }
}

function setupSvgInteractivity() {
  document.querySelectorAll('.comp-hitbox').forEach(function(el) {
    el.addEventListener('click', function(e) {
      e.stopPropagation();
      var id = el.getAttribute('data-id');
      var pos = el.getAttribute('data-pos');
      selectHitbox(id, pos);
    });
  });

  document.querySelectorAll('.plan-pos-badge').forEach(function(badge) {
    badge.addEventListener('click', function(e) {
      e.stopPropagation();
      var pos = badge.getAttribute('data-pos');
      if (activePos === pos) {
        deselectAll();
      } else {
        selectHitbox(null, pos);
      }
    });
  });

  var svg = document.querySelector('svg');
  if (svg) {
    svg.addEventListener('click', function(e) {
      if (e.target && e.target.closest && e.target.closest('.comp-hitbox, .plan-pos-badge, .draggable-legend, #bauteilmasse-box')) {
        return;
      }
      deselectAll();
    });
  }
}

function toggleBauteilmasse() {
  var box = document.getElementById('bauteilmasse-box');
  if (!box) return;
  var isExp = box.classList.toggle('is-expanded');
  var bg = document.getElementById('bauteilmasse-bg');
  var hBg = document.getElementById('bauteilmasse-header-bg');
  var title = box.querySelector('text');
  var btn = document.getElementById('bauteilmasse-toggle-btn');
  var btnText = document.getElementById('bauteilmasse-toggle-text');
  var content = document.getElementById('bauteilmasse-content');

  if (isExp) {
    if (bg) { bg.setAttribute('y', '675'); bg.setAttribute('height', '180'); }
    if (hBg) { hBg.setAttribute('y', '675'); }
    if (title) { title.setAttribute('y', '698'); }
    if (btn) { btn.setAttribute('transform', 'translate(770, 682)'); }
    if (btnText) { btnText.textContent = '▴ Details einklappen'; }
    if (content) { content.style.display = 'block'; }
  } else {
    if (bg) { bg.setAttribute('y', '818'); bg.setAttribute('height', '36'); }
    if (hBg) { hBg.setAttribute('y', '818'); }
    if (title) { title.setAttribute('y', '841'); }
    if (btn) { btn.setAttribute('transform', 'translate(770, 826)'); }
    if (btnText) { btnText.textContent = '▾ Details aufklappen'; }
    if (content) { content.style.display = 'none'; }
  }
}

function initDraggableLegend() {
  var legend = document.getElementById('svg-schrauben-legende');
  if (!legend) return;
  var svg = legend.ownerSVGElement || document.querySelector('svg');
  if (!svg) return;

  var isDragging = false;
  var startX = 0, startY = 0;
  var origX = 725, origY = 10;
  var hasMoved = false;

  function parseTranslate(transform) {
    if (!transform) return { x: 725, y: 10 };
    var match = transform.match(/translate\(\s*([-\d.]+)[,\s]+([-\d.]+)\s*\)/);
    return match ? { x: parseFloat(match[1]), y: parseFloat(match[2]) } : { x: 725, y: 10 };
  }

  try {
    var saved = localStorage.getItem('schrauben_legende_pos');
    if (saved) {
      var pos = JSON.parse(saved);
      if (typeof pos.x === 'number' && typeof pos.y === 'number') {
        legend.setAttribute('transform', 'translate(' + pos.x + ', ' + pos.y + ')');
      }
    }
  } catch (e) {}

  function getSVGCoords(e) {
    var pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    var ctm = svg.getScreenCTM();
    if (ctm) {
      return pt.matrixTransform(ctm.inverse());
    }
    var rect = svg.getBoundingClientRect();
    var vb = svg.viewBox.baseVal;
    return {
      x: vb.x + (e.clientX - rect.left) * (vb.width / rect.width),
      y: vb.y + (e.clientY - rect.top) * (vb.height / rect.height)
    };
  }

  legend.addEventListener('pointerdown', function(e) {
    if (e.button !== 0) return;
    if (e.target && e.target.closest && e.target.closest('.comp-hitbox')) {
      return;
    }
    isDragging = true;
    hasMoved = false;
    var current = parseTranslate(legend.getAttribute('transform'));
    origX = current.x;
    origY = current.y;
    var pt = getSVGCoords(e);
    startX = pt.x;
    startY = pt.y;
    try {
      legend.setPointerCapture(e.pointerId);
    } catch (err) {}
    legend.style.cursor = 'grabbing';
    e.stopPropagation();
  });

  legend.addEventListener('pointermove', function(e) {
    if (!isDragging) return;
    var pt = getSVGCoords(e);
    var dx = pt.x - startX;
    var dy = pt.y - startY;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
      hasMoved = true;
    }
    if (hasMoved) {
      var newX = Math.round(origX + dx);
      var newY = Math.round(origY + dy);
      legend.setAttribute('transform', 'translate(' + newX + ', ' + newY + ')');
    }
    e.stopPropagation();
  });

  function endDrag(e) {
    if (!isDragging) return;
    isDragging = false;
    legend.style.cursor = 'grab';
    try {
      legend.releasePointerCapture(e.pointerId);
    } catch (err) {}

    if (hasMoved) {
      var current = parseTranslate(legend.getAttribute('transform'));
      try {
        localStorage.setItem('schrauben_legende_pos', JSON.stringify(current));
      } catch (err) {}
    }
    e.stopPropagation();
  }

  legend.addEventListener('pointerup', endDrag);
  legend.addEventListener('pointercancel', endDrag);

  legend.addEventListener('dblclick', function(e) {
    legend.setAttribute('transform', 'translate(725, 10)');
    try {
      localStorage.removeItem('schrauben_legende_pos');
    } catch (err) {}
    e.stopPropagation();
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function() {
    initDraggableLegend();
    setupSvgInteractivity();
  });
} else {
  initDraggableLegend();
  setupSvgInteractivity();
}
